-- 0005: share links (API-only, hashed, version-locked) and the append-only audit log.

-- ---------------------------------------------------------------------------
-- share_links (decision #6): random token generated by the API, only its
-- SHA-256 is stored. Default validity 14 days, max 90. Revocation is
-- immediate and final. Locked to explicit sheet versions.
-- ---------------------------------------------------------------------------
create table public.share_links (
  id                 uuid primary key default gen_random_uuid(),
  org_id             uuid not null,
  project_id         uuid not null,
  token_hash         text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  sheet_version_ids  uuid[] not null check (cardinality(sheet_version_ids) > 0),
  scope              jsonb not null default '{}'::jsonb,
  allow_pdf_download boolean not null default false,
  hide_title_block   boolean not null default true,
  expires_at         timestamptz not null default (now() + interval '14 days'),
  revoked_at         timestamptz,
  created_by         uuid references auth.users (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (id, org_id),
  check (expires_at > created_at),
  check (expires_at <= created_at + interval '90 days'),
  foreign key (project_id, org_id) references public.projects (id, org_id) on delete cascade
);
create index share_links_project_idx on public.share_links (project_id);

create or replace function app.share_links_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    -- every locked version must belong to this project and org
    if exists (
      select 1
      from unnest(new.sheet_version_ids) as v(id)
      where not exists (
        select 1
        from public.sheet_versions sv
        join public.sheets s on s.id = sv.sheet_id and s.org_id = sv.org_id
        where sv.id = v.id and sv.org_id = new.org_id and s.project_id = new.project_id
      )
    ) then
      raise exception 'share link references sheet versions outside its project' using errcode = '23503';
    end if;
    if auth.uid() is not null then
      new.created_by := auth.uid();
    end if;
    new.revoked_at := null;
    return new;
  end if;

  -- UPDATE: only revocation is allowed, and it is final.
  if (to_jsonb(new) - 'revoked_at' - 'updated_at') is distinct from (to_jsonb(old) - 'revoked_at' - 'updated_at') then
    raise exception 'share links are immutable except for revocation' using errcode = '42501';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'share link revocation is final' using errcode = '42501';
  end if;
  return new;
end $$;

create trigger share_links_guard
  before insert or update on public.share_links
  for each row execute function app.share_links_guard();

-- ---------------------------------------------------------------------------
-- audit_log (SEC-35): append-only with a per-org SHA-256 hash chain.
-- No FK to orgs on purpose: a minimal audit trail outlives org offboarding.
-- ---------------------------------------------------------------------------
create table public.audit_log (
  id         bigint generated always as identity primary key,
  org_id     uuid not null,
  actor_id   uuid,
  actor_kind public.actor_kind not null,
  entity     text not null,
  entity_id  uuid,
  action     text not null,
  before     jsonb,
  after      jsonb,
  at         timestamptz not null default now(),
  prev_hash  text,
  hash       text not null
);
create index audit_log_org_idx on public.audit_log (org_id, id desc);
create index audit_log_entity_idx on public.audit_log (entity, entity_id);

create or replace function app.audit_log_chain() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  -- serialize writers per org so the chain is linear
  perform pg_advisory_xact_lock(hashtextextended('audit:' || new.org_id::text, 0));
  new.at := now();
  select a.hash into new.prev_hash
  from public.audit_log a
  where a.org_id = new.org_id
  order by a.id desc
  limit 1;
  new.hash := encode(extensions.digest(
    concat_ws('|',
      coalesce(new.prev_hash, ''),
      new.org_id::text,
      coalesce(new.actor_id::text, ''),
      new.actor_kind::text,
      new.entity,
      coalesce(new.entity_id::text, ''),
      new.action,
      coalesce(new.before::text, ''),
      coalesce(new.after::text, ''),
      to_char(new.at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
    ), 'sha256'), 'hex');
  return new;
end $$;

create trigger audit_log_chain
  before insert on public.audit_log
  for each row execute function app.audit_log_chain();

create or replace function app.audit_log_block_mutation() returns trigger
language plpgsql set search_path = '' as $$
begin
  raise exception 'audit_log is append-only (% blocked)', tg_op using errcode = '42501';
end $$;

create trigger audit_log_no_update_delete
  before update or delete on public.audit_log
  for each row execute function app.audit_log_block_mutation();
create trigger audit_log_no_truncate
  before truncate on public.audit_log
  for each statement execute function app.audit_log_block_mutation();

-- Explicit audit entry (used by the API for view/download/export events).
-- End users only: the actor is always the caller (auth.uid()), and only for orgs they belong to.
create or replace function app.write_audit(
  p_org uuid, p_entity text, p_entity_id uuid, p_action text,
  p_before jsonb default null, p_after jsonb default null
) returns bigint
language plpgsql volatile security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_id  bigint;
begin
  -- NB: inside a SECURITY DEFINER function current_user is the owner, so the
  -- caller's role cannot be inspected; require a JWT subject instead. System
  -- components (service_role / migration owner) insert into audit_log directly.
  if v_uid is null or not app.is_member(p_org) then
    raise exception 'not a member of org %', p_org using errcode = '42501';
  end if;
  insert into public.audit_log (org_id, actor_id, actor_kind, entity, entity_id, action, before, after)
  values (p_org, v_uid, 'user', p_entity, p_entity_id, p_action, p_before, p_after)
  returning id into v_id;
  return v_id;
end $$;
revoke all on function app.write_audit(uuid, text, uuid, text, jsonb, jsonb) from public;
grant execute on function app.write_audit(uuid, text, uuid, text, jsonb, jsonb) to authenticated;

-- Automatic audit of sensitive row changes.
create or replace function app.audit_row_change() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_uid    uuid := auth.uid();
  v_before jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_after  jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  v_org    uuid  := coalesce(v_after ->> 'org_id', v_before ->> 'org_id', v_after ->> 'id')::uuid;
  v_action text  := lower(tg_op);
  v_entity uuid  := coalesce(v_after ->> 'id', v_before ->> 'id')::uuid;
begin
  -- never copy secrets into the log
  v_before := v_before - 'token_hash';
  v_after  := v_after  - 'token_hash';
  if tg_table_name = 'boq_lines' then
    v_action := 'status_change';
    v_before := jsonb_build_object('status', v_before -> 'status');
    v_after  := jsonb_build_object('status', v_after -> 'status',
                                   'approved_by', v_after -> 'approved_by');
  elsif tg_table_name = 'share_links' and tg_op = 'UPDATE'
        and (v_before ->> 'revoked_at') is null and (v_after ->> 'revoked_at') is not null then
    v_action := 'revoke';
  end if;
  insert into public.audit_log (org_id, actor_id, actor_kind, entity, entity_id, action, before, after)
  values (v_org, v_uid, case when v_uid is null then 'system' else 'user' end::public.actor_kind,
          tg_table_name, v_entity, v_action, v_before, v_after);
  return null;
end $$;

create trigger memberships_audit
  after insert or update or delete on public.memberships
  for each row execute function app.audit_row_change();
create trigger share_links_audit
  after insert or update on public.share_links
  for each row execute function app.audit_row_change();
create trigger boq_lines_status_audit
  after update of status on public.boq_lines
  for each row when (old.status is distinct from new.status)
  execute function app.audit_row_change();
create trigger orgs_settings_audit
  after update of settings on public.orgs
  for each row when (old.settings is distinct from new.settings)
  execute function app.audit_row_change();
